// HasUser applies the HasEdge predicate on the "user" edge.
func HasUser() predicate.CraftingRecipe {
	return predicate.CraftingRecipe(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, UserTable, UserColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUserWith applies the HasEdge predicate on the "user" edge with a given conditions (other predicates).
func HasUserWith(preds ...predicate.User) predicate.CraftingRecipe {
	return predicate.CraftingRecipe(func(s *sql.Selector) {
		step := newUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasCharacterCrafting applies the HasEdge predicate on the "character_crafting" edge.
func HasCharacterCrafting() predicate.CraftingRecipe {
	return predicate.CraftingRecipe(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, CharacterCraftingTable, CharacterCraftingColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCharacterCraftingWith applies the HasEdge predicate on the "character_crafting" edge with a given conditions (other predicates).
func HasCharacterCraftingWith(preds ...predicate.CharacterCrafting) predicate.CraftingRecipe {
	return predicate.CraftingRecipe(func(s *sql.Selector) {
		step := newCharacterCraftingStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CraftingRecipe) predicate.CraftingRecipe {
	return predicate.CraftingRecipe(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CraftingRecipe) predicate.CraftingRecipe {
	return predicate.CraftingRecipe(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CraftingRecipe) predicate.CraftingRecipe {
	return predicate.CraftingRecipe(sql.NotPredicates(p))
}
